'use strict';

// MODULES //

var tape = require( 'tape' );
var MIN_SAFE_INTEGER = require( '@stdlib/constants/float64/min-safe-integer' );
var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var Int64 = require( '@stdlib/number/int64/ctor' );
var toWords = require( './../lib/main.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof toWords, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a two-element numeric array containing integers', function test( t ) {
	var a;
	var w;

	a = new Int64( 4294967296 );
	w = toWords( a );

	t.strictEqual( isInteger( w[0] ), true, 'returns expected value' );
	t.strictEqual( isInteger( w[1] ), true, 'returns expected value' );

	t.end();
});

tape( 'the function splits a 64-bit signed integer into a higher order word and a lower order word (positive)', function test( t ) {
	var expected;
	var values;
	var w;
	var i;

	values = [
		new Int64( 0 ),
		new Int64( 1 ),
		new Int64( 4294967295 ),
		new Int64( 4294967296 ),
		new Int64( 10000000000 ),
		Int64.of( 12, 34 )
	];

	expected = [
		[ 0, 0 ],
		[ 0, 1 ],
		[ 0, 4294967295 ],
		[ 1, 0 ],
		[ 2, 1410065408 ],
		[ 12, 34 ]
	];

	for ( i = 0; i < values.length; i++ ) {
		w = toWords( values[ i ] );
		t.strictEqual( w[ 0 ], expected[ i ][ 0 ], 'returns expected value' );
		t.strictEqual( w[ 1 ], expected[ i ][ 1 ], 'returns expected value' );
	}
	t.end();
});

tape( 'the function splits a 64-bit signed integer into a higher order word and a lower order word (negative)', function test( t ) {
	var expected;
	var values;
	var w;
	var i;

	values = [
		-1,
		-2,
		-4294967295,
		-4294967296,
		-4294967298,
		-1000000000000,
		MIN_SAFE_INTEGER
	];

	expected = [
		[ 4294967295, 4294967295 ],
		[ 4294967295, 4294967294 ],
		[ 4294967295, 1 ],
		[ 4294967295, 0 ],
		[ 4294967294, 4294967294 ],
		[ 4294967063, 727379968 ],
		[ 4292870144, 1 ]
	];

	for ( i = 0; i < values.length; i++ ) {
		w = toWords( new Int64( values[ i ] ) );
		t.strictEqual( w[ 0 ], expected[ i ][ 0 ], 'returns expected value' );
		t.strictEqual( w[ 1 ], expected[ i ][ 1 ], 'returns expected value' );
	}
	t.end();
});
